package io.knowledgebrain.integration;
import java.util.*;import java.time.*;import jakarta.servlet.Filter;import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.*;import static org.mockito.Mockito.*;import org.springframework.context.annotation.*;import org.springframework.core.env.MapPropertySource;import org.springframework.mock.web.MockServletContext;import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import org.springframework.web.context.support.AnnotationConfigWebApplicationContext;import org.springframework.web.servlet.config.annotation.EnableWebMvc;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import io.micrometer.core.instrument.MeterRegistry;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class GitHubSyncHistorySecurityTest {
 @Configuration(proxyBeanMethods=false) @EnableWebMvc @EnableWebSecurity @Import({SecurityConfiguration.class,GitHubController.class,GitHubErrors.class})
 static class Web {@Bean GitHubStore store(){return mock(GitHubStore.class);}@Bean GitHubClient remote(){return mock(GitHubClient.class);}@Bean SpaceAuthorizationClient authority(){return mock(SpaceAuthorizationClient.class);}@Bean MeterRegistry metrics(){return new SimpleMeterRegistry();}}
 AnnotationConfigWebApplicationContext context;MockMvc mvc;GitHubStore store;GitHubClient remote;SpaceAuthorizationClient authority;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space=ids.next(),repo=ids.next(),actor=ids.next();String token="a".repeat(43),path="/api/spaces/"+space+"/github/repositories/"+repo+"/syncs";
 void start(boolean enabled){if(context!=null)context.close();context=new AnnotationConfigWebApplicationContext();context.setServletContext(new MockServletContext());context.getEnvironment().getPropertySources().addFirst(new MapPropertySource("github-sync-security",Map.of("brain.integration.api.enabled",Boolean.toString(enabled),"brain.integration.activity-export.enabled","false","brain.integration.browser-origin","https://localhost:8443")));context.register(Web.class);context.refresh();store=context.getBean(GitHubStore.class);remote=context.getBean(GitHubClient.class);authority=context.getBean(SpaceAuthorizationClient.class);mvc=MockMvcBuilders.webAppContextSetup(context).addFilters(context.getBean("springSecurityFilterChain",Filter.class)).build();when(authority.authorize(eq(space),eq(token),eq(false),anyString())).thenReturn(actor);}
 @AfterEach void close(){if(context!=null)context.close();}
 @Test void actualSecurityChainAllowsOnlyEnabledGetThenChecksCurrentAuthority()throws Exception{start(true);when(store.syncs(space,repo,null,20)).thenReturn(new GitHubStore.SyncPage(List.of(),null));mvc.perform(get(path).secure(true).cookie(new Cookie("__Host-brain_guest",token))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(content().json("{\"items\":[],\"nextBefore\":null}"));when(authority.authorize(eq(space),eq(token),eq(false),anyString())).thenThrow(new ResponseStatusException(HttpStatus.FORBIDDEN));mvc.perform(get(path).secure(true).cookie(new Cookie("__Host-brain_guest",token))).andExpect(status().isForbidden()).andExpect(header().string("Cache-Control","no-store"));verify(authority,times(2)).authorize(eq(space),eq(token),eq(false),anyString());verify(store).syncs(space,repo,null,20);verifyNoMoreInteractions(store);verifyNoInteractions(remote);}
 @Test void disabledExtraPathsAndWritesRemainBlockedWhileEnabledInputGuardRuns()throws Exception{start(false);mvc.perform(get(path).secure(true).cookie(new Cookie("__Host-brain_guest",token))).andExpect(status().isForbidden());verifyNoInteractions(store,authority,remote);start(true);mvc.perform(post(path).secure(true).cookie(new Cookie("__Host-brain_guest",token))).andExpect(status().isForbidden());mvc.perform(delete(path).secure(true).cookie(new Cookie("__Host-brain_guest",token))).andExpect(status().isForbidden());mvc.perform(get(path+"/extra").secure(true).cookie(new Cookie("__Host-brain_guest",token))).andExpect(status().isForbidden());mvc.perform(get(path).secure(true).cookie(new Cookie("__Host-brain_guest",token)).param("before","0")).andExpect(status().isBadRequest()).andExpect(header().string("Cache-Control","no-store"));verifyNoInteractions(store,remote);}
}
